/// git/forge-icon.tsx ForgeBrandIcon: the forge's brand mark tinted [color],
/// falling back to the generic GitPullRequest glyph for an unknown forge.
class ForgeBrandIcon extends StatelessWidget {
  const ForgeBrandIcon({super.key, required this.forge, required this.size, required this.color});
  final String forge;
  final double size;
  final Color color;

  @override
  Widget build(BuildContext context) {
    final svg = forgeBrandSvgs[forge.isEmpty ? 'github' : forge];
    final fallback = Icon(LucideIcons.gitPullRequest300, size: size, color: color);
    if (svg == null) return fallback;
    return SvgPicture.string(
      svg,
      width: size,
      height: size,
      theme: SvgTheme(currentColor: color),
      errorBuilder: (_, _, _) => fallback,
    );
  }
}
